def choose_move(observation):
    width = observation['grid_width']
    height = observation['grid_height']
    x, y = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = observation.get('obstacles', [])
    remaining = observation.get('remaining_resource_count', 0)
    obstacles_set = set(tuple(pos) for pos in obstacles)
    # Basic heuristic: move towards the closest resource if any, else towards opponent
    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    if resources:
        target = min(resources, key=lambda r: dist((x,y), (r['x'], r['y'])))
    else:
        target = (opp_x, opp_y)
    dx, dy = 0, 0
    if target:
        tx, ty = target
        if tx > x and (x+1, y) not in obstacles_set and x+1 < width:
            dx = 1
        elif tx < x and (x-1, y) not in obstacles_set and x-1 >= 0:
            dx = -1
        elif ty > y and (x, y+1) not in obstacles_set and y+1 < height:
            dy = 1
        elif ty < y and (x, y-1) not in obstacles_set and y-1 >= 0:
            dy = -1
        else:
            # if blocked, try to stay
            dx, dy = 0, 0
    return [dx, dy]
